package it.carmine.streamplayer.lab211;
import java.net.*;import java.util.*;import java.util.regex.*;import java.nio.charset.StandardCharsets;
/** Public anime catalogue and explicit episode/server links, not domain-only recognition. */
public final class AnimeCatalog implements LabPipeline.CatalogAdapter {
 private final boolean saturn;public AnimeCatalog(boolean saturn){this.saturn=saturn;}
 public String name(){return saturn?"AnimeSaturn":"AnimeWorld";}
 public String search(String base,String query)throws Exception{return LabPipeline.origin(base)+(query.isEmpty()?"/":(saturn?"/filter?key=":"/search?keyword=")+URLEncoder.encode(query,"UTF-8"));}
 public List<LabPipeline.Title> titles(LabPipeline.Page page){List<LabPipeline.Title> out=new ArrayList<>();Set<String> seen=new HashSet<>();Matcher a=Pattern.compile("(?is)<a\\b([^>]*)>(.*?)</a>").matcher(page.text());while(a.find()&&out.size()<100){Map<String,String> at=LabPipeline.attrs(a.group(1));String url=LabPipeline.absolute(page.url,at.getOrDefault("href",""));if(url.isEmpty()||!LabPipeline.host(url).equals(LabPipeline.host(page.url))||!URI.create(url).getPath().startsWith(saturn?"/anime/":"/play/"))continue;Matcher img=Pattern.compile("(?is)<img\\b[^>]*>").matcher(a.group(2));if(!img.find())continue;Map<String,String> image=LabPipeline.attrs(img.group());String poster=LabPipeline.absolute(page.url,image.getOrDefault("data-src",image.getOrDefault("src","")));String title=image.getOrDefault("alt",at.getOrDefault("title",""));if(!poster.isEmpty()&&!title.isEmpty()&&seen.add(url))out.add(new LabPipeline.Title(title,poster,url));}return out;}
 public List<LabPipeline.Source> sources(LabPipeline.Page page)throws Exception{
  List<LabPipeline.Source> out=new ArrayList<>();Set<String> seen=new HashSet<>();Matcher tags=Pattern.compile("(?is)<[a-z]+\\b[^>]*>").matcher(page.text());while(tags.find()&&out.size()<100){Map<String,String> a=LabPipeline.attrs(tags.group());String data=a.getOrDefault("x-data","");if(saturn&&data.startsWith("watchPage(")){int end=data.lastIndexOf(')');Object value=LabPipeline.publicJson(data.substring(data.indexOf('(')+1,end));if(value instanceof Map){Map<?,?> object=(Map<?,?>)value;Object servers=object.get("servers");if(servers instanceof List)for(Object item:(List<?>)servers)if(item instanceof Map){Map<?,?> server=(Map<?,?>)item;String url=LabPipeline.absolute(page.url,String.valueOf(server.get("link")));if(!url.isEmpty()&&URI.create(url).getPath().matches("/embed/[0-9]+")&&seen.add(url))out.add(new LabPipeline.Source(url,"AnimeSaturn · "+String.valueOf(server.get("name")),page.url));}Object initial=object.get("initialVideoUrl");if(out.isEmpty()&&initial instanceof String){String u=LabPipeline.absolute(page.url,(String)initial);if(!u.isEmpty()&&URI.create(u).getPath().matches("/embed/[0-9]+"))out.add(new LabPipeline.Source(u,"AnimeSaturn",page.url));}}}
   if(!saturn&&a.containsKey("data-episode-id")&&a.getOrDefault("data-id","").matches("[A-Za-z0-9_-]{1,128}")){String id=a.get("data-id"),url=LabPipeline.origin(page.url)+"/api/episode/info?id="+URLEncoder.encode(id,"UTF-8")+"&alt=0";if(seen.add(url))out.add(new LabPipeline.Source(url,"Episodio "+a.get("data-episode-id"),page.url));}
   if(saturn&&a.getOrDefault("class","").contains("ep-tile")){String url=LabPipeline.absolute(page.url,a.getOrDefault("href",""));if(!url.isEmpty()&&LabPipeline.host(url).equals(LabPipeline.host(page.url))&&seen.add(url))out.add(new LabPipeline.Source(url,"Episodio · "+URI.create(url).getPath().substring(URI.create(url).getPath().lastIndexOf('/')+1),page.url));}
  }return out;
 }
}
